import assert from 'node:assert/strict'
import {chromium} from 'playwright-core'

const url=process.env.EXO_QA_URL||'http://127.0.0.1:5173'
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist']})
const context=await browser.newContext({viewport:{width:1440,height:900}})
const page=await context.newPage()
const pageErrors=[]
page.on('pageerror',error=>pageErrors.push(error.message))
const settings=()=>page.getByRole('button',{name:'Open Studio Settings'})
const leftExtras=()=>page.locator('.clo-left-3d-double-bars[aria-label^="EXO additional 3D controls"]')
const rightExtras=()=>page.locator('.clo-reference-dual-bars[aria-label="Additional EXO tools selected in Settings"]')

try{
  await page.goto(`${url}/?desktop=1&engine=clothcraft&testSession=tool-index-20261017`,{waitUntil:'domcontentloaded'})
  await settings().waitFor({timeout:60000})
  assert.equal(await leftExtras().count(),0,'left extra strip hidden by default')
  assert.equal(await rightExtras().count(),0,'right extra strip hidden by default')
  await settings().click()
  await page.getByTestId('settings-tab-toolIndex').click()
  assert.equal(await page.getByTestId('tool-index-left').locator('[data-exo-extra-id]').count(),6)
  assert.equal(await page.getByTestId('tool-index-right').locator('[data-exo-extra-id]').count(),31)
  const search=page.getByRole('textbox',{name:'Search extra tools'})
  await search.fill('wireframe')
  assert.equal(await page.locator('.studio-index-tool').count(),2,'wireframe searchable on both sides')
  await search.fill('')
  await page.getByRole('button',{name:'Add 3D fabric hand tool to left toolbar'}).click()
  await page.getByRole('button',{name:'Add Grading browser to right toolbar'}).click()
  await page.getByRole('button',{name:'Apply'}).click()
  assert.equal(await leftExtras().locator('button[title="EXO 3D fabric hand tool"]').count(),1)
  assert.equal(await rightExtras().locator('button[aria-label="Grading browser"]').count(),1)
  await page.reload({waitUntil:'domcontentloaded'})
  await settings().waitFor({timeout:60000})
  assert.equal(await leftExtras().locator('button[title="EXO 3D fabric hand tool"]').count(),1,'left selection persists across reload')
  assert.equal(await rightExtras().locator('button[aria-label="Grading browser"]').count(),1,'right selection persists across reload')
  await settings().click()
  await page.getByTestId('settings-tab-toolIndex').click()
  assert.equal(await page.getByRole('button',{name:'Remove 3D fabric hand tool from left toolbar'}).getAttribute('aria-pressed'),'true')
  assert.equal(await page.getByRole('button',{name:'Remove Grading browser from right toolbar'}).getAttribute('aria-pressed'),'true')
  await page.screenshot({path:'research/screenshots/exo-v2-tool-index-20261017.png',fullPage:false})
  await page.getByRole('button',{name:'Remove all left extra tools'}).click()
  await page.getByRole('button',{name:'Remove all right extra tools'}).click()
  await page.getByRole('button',{name:'Apply'}).click()
  assert.equal(await leftExtras().count(),0)
  assert.equal(await rightExtras().count(),0)
  await page.reload({waitUntil:'domcontentloaded'})
  await settings().waitFor({timeout:60000})
  assert.equal(await leftExtras().count(),0,'left hide persists across reload')
  assert.equal(await rightExtras().count(),0,'right hide persists across reload')
  assert.ok((await page.locator('[data-clo-slot^="2d:"]').count())>0,'original CLO 2D controls remain')
  assert.ok((await page.locator('[data-clo-slot^="3d:"]').count())>0,'original CLO 3D controls remain')
  assert.equal(pageErrors.length,0,`page errors: ${pageErrors.join('; ')}`)
  console.log('PASS Tool Index: default hidden, 6 left / 31 right catalogued, search, per-tool restore, persistence, removal, original CLO toolbars retained')
  console.log('Screenshot: research/screenshots/exo-v2-tool-index-20261017.png')
}finally{await browser.close()}
